package com.wethaq.app;

import android.app.Activity;
import android.content.Context;
import android.content.SharedPreferences;
import android.graphics.Color;
import android.graphics.Typeface;
import android.net.ConnectivityManager;
import android.net.NetworkInfo;
import android.os.Bundle;
import android.os.Handler;
import android.os.Looper;
import android.view.Gravity;
import android.view.View;
import android.widget.Button;
import android.widget.EditText;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.TextView;
import org.json.JSONArray;
import org.json.JSONObject;
import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.net.HttpURLConnection;
import java.net.URL;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public final class MainActivity extends Activity {
 private static final String API="https://wethaq-backend-production.up.railway.app",PREFS="wethaq",TOKEN="token",USER_ID="wethaq_id",NAME="name",BIRTH_YEAR="birth_year",CONTACTS="saved_contacts";
 private static final String FOUNDER_TITLE="المؤسس: حاتم حسين الحاج رمضان";
 private final ExecutorService io=Executors.newSingleThreadExecutor(); private final Handler main=new Handler(Looper.getMainLooper()); private SharedPreferences prefs; private LinearLayout root,content,messageList; private TextView title,status; private String activeContactId,activeContactName; private EditText messageInput; private Runnable poller;
 private final int bg=Color.rgb(9,17,29),panel=Color.rgb(18,31,48),panel2=Color.rgb(25,42,63),text=Color.WHITE,muted=Color.rgb(180,194,208),accent=Color.rgb(70,145,170);
 @Override protected void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences(PREFS,MODE_PRIVATE);if(hasToken())showHome();else showLogin();}
 @Override protected void onResume(){super.onResume();if(activeContactId!=null)startPolling();}
 @Override protected void onPause(){super.onPause();stopPolling();}
 @Override protected void onDestroy(){stopPolling();io.shutdownNow();super.onDestroy();}
 private boolean hasToken(){return prefs.getString(TOKEN,"").length()>10;}
 private void base(String heading){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(bg);root.setPadding(28,28,28,28);LinearLayout h=new LinearLayout(this);h.setGravity(Gravity.CENTER_VERTICAL);h.setPadding(18,14,18,14);h.setBackgroundColor(panel);title=tv(heading,22,text,Typeface.BOLD);h.addView(title,new LinearLayout.LayoutParams(0,-2,1));root.addView(h,new LinearLayout.LayoutParams(-1,-2));status=tv("",13,muted,Typeface.NORMAL);status.setGravity(Gravity.CENTER);status.setPadding(8,10,8,8);root.addView(status,new LinearLayout.LayoutParams(-1,-2));content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);ScrollView s=new ScrollView(this);s.setFillViewport(true);s.addView(content,new ScrollView.LayoutParams(-1,-1));root.addView(s,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);}
 private void showLogin(){stopPolling();activeContactId=null;base("وَثاق");TextView w=tv("هويتك الرقمية الآمنة",22,text,Typeface.BOLD);w.setGravity(Gravity.CENTER);content.addView(w,lp(18,18,18,18));EditText n=field("الاسم الثلاثي"),y=field("سنة الميلاد");y.setInputType(2);content.addView(n,lp(0,8,0,8));content.addView(y,lp(0,8,0,8));Button b=button("دخول / إنشاء الهوية");content.addView(b,lp(0,18,0,8));b.setOnClickListener(v->{String name=n.getText().toString().trim(),year=y.getText().toString().trim();if(name.split("\\s+").length<3||year.length()!=4){setStatus("أدخل اسمًا من ثلاثة مقاطع وسنة صحيحة.",true);return;}login(name,year);});}
 private void login(String name,String year){io.execute(()->{try{JSONObject body=new JSONObject().put("name",name).put("birthYear",Integer.parseInt(year)).put("deviceKey",getDeviceKey());HttpResult r=request("POST","/api/identity",body.toString(),null);if(r.code>=200&&r.code<300){JSONObject d=new JSONObject(r.body),u=d.getJSONObject("user");saveSession(d.getString("token"),u.getString("wethaq_id"),u.getString("name"),u.optInt("birth_year"));main.post(this::showHome);}else main.post(()->setStatus(errorText(r),true));}catch(Exception e){main.post(()->setStatus("تعذر الاتصال بالخادم. تحقق من الإنترنت.",true));}});}
 private void showHome(){stopPolling();activeContactId=null;base(FOUNDER_TITLE);LinearLayout id=card();id.addView(tv(prefs.getString(NAME,"مستخدم وَثاق"),20,text,Typeface.BOLD));id.addView(tv("المعرف: "+prefs.getString(USER_ID,""),14,muted,Typeface.NORMAL),lp(0,8,0,0));content.addView(id,lp(0,4,0,12));Button search=button("البحث عن مستخدم"),contacts=button("جهات الاتصال"),logout=button("تسجيل الخروج");content.addView(search,lp(0,6,0,6));content.addView(contacts,lp(0,6,0,6));content.addView(logout,lp(0,6,0,6));search.setOnClickListener(v->showSearch());contacts.setOnClickListener(v->showContacts());logout.setOnClickListener(v->{prefs.edit().remove(TOKEN).apply();showLogin();});setStatus(isOnline()?"متصل":"غير متصل",false);if(isOnline())refreshMe();}
 private void showSearch(){stopPolling();base("البحث");Button back=button("← العودة");content.addView(back,lp(0,0,0,12));EditText q=field("الاسم أو معرف وَثاق");Button go=button("بحث");content.addView(q,lp(0,4,0,8));content.addView(go,lp(0,4,0,12));LinearLayout results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);content.addView(results,lp(0,4,0,0));back.setOnClickListener(v->showHome());go.setOnClickListener(v->search(q.getText().toString().trim(),results));}
 private void search(String q,LinearLayout results){if(q.length()<2){setStatus("أدخل حرفين على الأقل.",true);return;}setStatus("جاري البحث…",false);io.execute(()->{try{HttpResult r=request("GET","/api/search?q="+URLEncoder.encode(q,"UTF-8"),null,null);if(r.code==200){JSONArray a=new JSONObject(r.body).optJSONArray("users");main.post(()->{results.removeAllViews();if(a==null||a.length()==0)results.addView(tv("لا توجد نتائج.",16,muted,Typeface.NORMAL),lp(8,16,8,8));else for(int i=0;i<a.length();i++){JSONObject u=a.optJSONObject(i);if(u!=null)addUserResult(results,u);}});}else main.post(()->setStatus(errorText(r),true));}catch(Exception e){main.post(()->setStatus("فشل البحث. تحقق من الاتصال.",true));}});}
 private void addUserResult(LinearLayout results,JSONObject u){LinearLayout row=card();String id=u.optString("wethaq_id"),name=u.optString("name");TextView n=tv(name,18,text,Typeface.BOLD),i=tv(id+(u.optBoolean("online")?" • متصل":""),13,muted,Typeface.NORMAL);Button save=button("حفظ في جهات الاتصال");row.addView(n);row.addView(i,lp(0,5,0,8));row.addView(save);results.addView(row,lp(0,5,0,8));save.setOnClickListener(v->saveContact(id,name,save));}
 private void saveContact(String id,String name,Button save){io.execute(()->{try{HttpResult r=request("POST","/api/contacts",new JSONObject().put("wethaqId",id).toString(),auth());if(r.code>=200&&r.code<300){saveLocalContact(id,name);main.post(()->{save.setText("تم الحفظ ✓");save.setEnabled(false);setStatus("تم حفظ "+name+" في جهات الاتصال.",false);});}else main.post(()->setStatus(errorText(r),true));}catch(Exception e){main.post(()->setStatus("تعذر حفظ جهة الاتصال.",true));}});}
 private void showContacts(){stopPolling();base("جهات الاتصال");Button back=button("← العودة");content.addView(back,lp(0,0,0,12));LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);content.addView(list,lp(0,0,0,0));back.setOnClickListener(v->showHome());renderContacts(list);if(isOnline())io.execute(()->{try{HttpResult r=request("GET","/api/contacts",null,auth());if(r.code==200){JSONArray a=new JSONObject(r.body).optJSONArray("contacts");if(a!=null)for(int i=0;i<a.length();i++){JSONObject u=a.optJSONObject(i);if(u!=null)saveLocalContact(u.optString("wethaq_id"),u.optString("name"));}main.post(()->renderContacts(list));}}catch(Exception ignored){}});}
 private void renderContacts(LinearLayout list){list.removeAllViews();JSONArray a=getLocalContacts();if(a.length()==0){list.addView(tv("لا توجد جهات اتصال محفوظة بعد.",16,muted,Typeface.NORMAL),lp(8,18,8,8));return;}for(int i=0;i<a.length();i++){JSONObject u=a.optJSONObject(i);if(u!=null)addContactRow(list,u);}}
 private void addContactRow(LinearLayout list,JSONObject u){String id=u.optString("wethaq_id"),name=u.optString("name");Button row=button(name+"\n"+id);row.setGravity(Gravity.CENTER_VERTICAL|Gravity.RIGHT);list.addView(row,lp(0,5,0,5));row.setOnClickListener(v->showConversation(id,name));}
 private JSONArray getLocalContacts(){try{return new JSONArray(prefs.getString(CONTACTS,"[]"));}catch(Exception e){return new JSONArray();}}
 private void saveLocalContact(String id,String name){try{JSONArray old=getLocalContacts(),out=new JSONArray();boolean found=false;for(int i=0;i<old.length();i++){JSONObject x=old.optJSONObject(i);if(x==null)continue;if(id.equals(x.optString("wethaq_id"))){out.put(new JSONObject().put("wethaq_id",id).put("name",name));found=true;}else out.put(x);}if(!found)out.put(new JSONObject().put("wethaq_id",id).put("name",name));prefs.edit().putString(CONTACTS,out.toString()).apply();}catch(Exception ignored){}}
 private void showConversation(String id,String name){stopPolling();activeContactId=id;activeContactName=name;base(name);Button back=button("← جهات الاتصال");content.addView(back,lp(0,0,0,8));messageList=new LinearLayout(this);messageList.setOrientation(LinearLayout.VERTICAL);ScrollView s=new ScrollView(this);s.setFillViewport(true);s.addView(messageList,new ScrollView.LayoutParams(-1,-2));content.addView(s,new LinearLayout.LayoutParams(-1,0,1));LinearLayout composer=new LinearLayout(this);messageInput=field("اكتب رسالتك…");Button send=button("إرسال");composer.addView(messageInput,new LinearLayout.LayoutParams(0,-2,1));composer.addView(send,new LinearLayout.LayoutParams(-2,-2));root.addView(composer,new LinearLayout.LayoutParams(-1,-2));back.setOnClickListener(v->showContacts());send.setOnClickListener(v->sendMessage(messageInput.getText().toString().trim()));loadMessages();startPolling();}
 private void loadMessages(){if(!isOnline()){setStatus("لا يوجد اتصال بالإنترنت.",true);return;}io.execute(()->{try{HttpResult r=request("GET","/api/messages/"+URLEncoder.encode(activeContactId,"UTF-8"),null,auth());if(r.code==200)main.post(()->renderMessages(new JSONObject(r.body).optJSONArray("messages")));else main.post(()->setStatus(errorText(r),true));}catch(Exception e){main.post(()->setStatus("تعذر تحميل المحادثة.",true));}});}
 private void renderMessages(JSONArray a){if(messageList==null)return;messageList.removeAllViews();if(a==null||a.length()==0){messageList.addView(tv("لا توجد رسائل. ابدأ المحادثة.",15,muted,Typeface.NORMAL),lp(8,20,8,8));return;}for(int i=0;i<a.length();i++){JSONObject m=a.optJSONObject(i);if(m==null)continue;boolean mine=String.valueOf(m.optInt("sender_id",-1)).equals(prefs.getString("numeric_id","-2"));LinearLayout b=card();b.setBackgroundColor(mine?panel2:panel);b.addView(tv(m.optString("body"),16,text,Typeface.NORMAL));b.addView(tv(m.optString("status")+" • "+m.optString("created_at"),11,muted,Typeface.NORMAL),lp(0,5,0,0));messageList.addView(b,lp(mine?60:0,5,mine?0:60,5));}}
 private void sendMessage(String body){if(body.isEmpty())return;if(!isOnline()){setStatus("يجب الاتصال بالإنترنت لإرسال الرسائل.",true);return;}messageInput.setText("");io.execute(()->{try{HttpResult r=request("POST","/api/messages",new JSONObject().put("to",activeContactId).put("body",body).toString(),auth());if(r.code>=200&&r.code<300)main.post(this::loadMessages);else main.post(()->setStatus(errorText(r),true));}catch(Exception e){main.post(()->setStatus("انقطع الاتصال أثناء الإرسال.",true));}});}
 private void startPolling(){stopPolling();poller=()->{if(activeContactId!=null&&isOnline())loadMessages();if(activeContactId!=null)main.postDelayed(poller,5000);};main.postDelayed(poller,5000);}
 private void stopPolling(){if(poller!=null)main.removeCallbacks(poller);poller=null;}
 private void refreshMe(){io.execute(()->{try{HttpResult r=request("GET","/api/me",null,auth());if(r.code==200){JSONObject u=new JSONObject(r.body).getJSONObject("user");prefs.edit().putString(USER_ID,u.getString("wethaq_id")).putString(NAME,u.getString("name")).putString("numeric_id",String.valueOf(u.getInt("id"))).apply();}}catch(Exception ignored){}});}
 private String getDeviceKey(){String k=prefs.getString("device_key","");if(k.length()>=24)return k;k="wethaq-"+java.util.UUID.randomUUID()+"-"+java.util.UUID.randomUUID();prefs.edit().putString("device_key",k).apply();return k;}
 private void saveSession(String t,String id,String name,int year){prefs.edit().putString(TOKEN,t).putString(USER_ID,id).putString(NAME,name).putInt(BIRTH_YEAR,year).apply();}
 private String auth(){return "Bearer "+prefs.getString(TOKEN,"");}
 private HttpResult request(String method,String path,String body,String authorization)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(API+path).openConnection();c.setRequestMethod(method);c.setConnectTimeout(12000);c.setReadTimeout(15000);c.setRequestProperty("Accept","application/json");if(authorization!=null)c.setRequestProperty("Authorization",authorization);if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json; charset=UTF-8");byte[] x=body.getBytes(StandardCharsets.UTF_8);c.setFixedLengthStreamingMode(x.length);try(OutputStream o=c.getOutputStream()){o.write(x);}}int code=c.getResponseCode();InputStream in=code>=400?c.getErrorStream():c.getInputStream();String response=read(in);c.disconnect();return new HttpResult(code,response);}
 private String read(InputStream in)throws Exception{if(in==null)return "";StringBuilder b=new StringBuilder();try(BufferedReader r=new BufferedReader(new InputStreamReader(in,StandardCharsets.UTF_8))){String l;while((l=r.readLine())!=null)b.append(l);}return b.toString();}
 private String errorText(HttpResult r){try{String e=new JSONObject(r.body).optString("error","");if("identity_claimed".equals(e))return"هذه الهوية مرتبطة بجهاز آخر.";if("user_not_found".equals(e))return"المستخدم غير موجود.";if("unauthorized".equals(e)||"invalid_token".equals(e))return"انتهت الجلسة. سجّل الدخول من جديد.";return e.length()>0?e:"حدث خطأ في الخادم ("+r.code+").";}catch(Exception e){return"حدث خطأ في الخادم ("+r.code+").";}}
 private boolean isOnline(){try{ConnectivityManager c=(ConnectivityManager)getSystemService(Context.CONNECTIVITY_SERVICE);NetworkInfo n=c==null?null:c.getActiveNetworkInfo();return n!=null&&n.isConnected();}catch(Exception e){return false;}}
 private TextView tv(String s,float z,int c,int st){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);t.setTypeface(Typeface.DEFAULT,st);t.setTextDirection(View.TEXT_DIRECTION_ANY_RTL);return t;}
 private EditText field(String h){EditText e=new EditText(this);e.setHint(h);e.setHintTextColor(Color.rgb(130,145,160));e.setTextColor(text);e.setTextSize(16);e.setPadding(18,14,18,14);e.setBackgroundColor(panel);e.setTextDirection(View.TEXT_DIRECTION_ANY_RTL);return e;}
 private Button button(String s){Button b=new Button(this);b.setText(s);b.setTextColor(text);b.setTextSize(15);b.setAllCaps(false);b.setPadding(18,12,18,12);b.setBackgroundColor(accent);return b;}
 private LinearLayout card(){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(18,16,18,16);c.setBackgroundColor(panel);return c;}
 private LinearLayout.LayoutParams lp(int l,int t,int r,int b){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(l,t,r,b);return p;}
 private void setStatus(String s,boolean e){if(status!=null){status.setText(s);status.setTextColor(e?Color.rgb(255,125,125):muted);}}
 private static final class HttpResult{final int code;final String body;HttpResult(int c,String b){code=c;body=b;}}
}
